flow.code:
. {
Get-Location
}

. {
git --version
}

. {
$practiceRoot = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'ProgressPal Git oving'
if (Test-Path -LiteralPath $practiceRoot) { throw 'STOPP: Mappen finnes allerede. Ikke overskriv den.' }
New-Item -ItemType Directory -Path $practiceRoot -ErrorAction Stop
Set-Location -LiteralPath $practiceRoot -ErrorAction Stop
Get-Location
}

. {
Get-ChildItem -Force
}

. {
$practiceRoot = Join-Path ([Environment]::GetFolderPath('MyDocuments')) 'ProgressPal Git oving'
Set-Location -LiteralPath $practiceRoot -ErrorAction Stop
Get-Location
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
if (@(Get-ChildItem -Force).Count -ne 0) { throw 'STOPP: Opprettelse krever en ny, tom ovingsmappe.' }
git init -b main
if ($LASTEXITCODE -ne 0) { throw 'STOPP: Git kunne ikke opprette repositoryet.' }
git status
}

. {
Get-ChildItem -Force
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git config --local user.name "Git-elev"
git config --local user.email "git-elev@example.invalid"
git config --local --get user.name
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
$names = @('README.txt', 'plan.txt', '.gitignore', 'kladde.txt')
foreach ($name in $names) {
  if (Test-Path -LiteralPath $name) { throw ('STOPP: Filen finnes allerede: ' + $name) }
}
Set-Content -LiteralPath 'README.txt' -Value @('Turplan', 'Dagstur langs elva.') -Encoding ASCII -ErrorAction Stop
Set-Content -LiteralPath 'plan.txt' -Value 'Husk vann.' -Encoding ASCII -ErrorAction Stop
Set-Content -LiteralPath '.gitignore' -Value 'kladde.txt' -Encoding ASCII -ErrorAction Stop
Set-Content -LiteralPath 'kladde.txt' -Value 'Et forslag jeg ikke vil ha med i historikken.' -Encoding ASCII -ErrorAction Stop
Get-ChildItem -Force
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
notepad.exe .\README.txt
}

. {
Get-Content -LiteralPath 'README.txt'
git status --short
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git add -- .gitignore README.txt plan.txt
if ($LASTEXITCODE -ne 0) { throw "STOPP: Filene kunne ikke klargjores." }
git diff --cached --name-only
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git --no-pager diff --cached
git commit -m "Start turplanen"
if ($LASTEXITCODE -ne 0) { throw "STOPP: Commit ble ikke laget. Les feilmeldingen." }
git status --short
}

. {
git --no-pager log --oneline -1
git --no-pager show HEAD:README.txt
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
notepad.exe .\README.txt
notepad.exe .\plan.txt
}

. {
git status --short
git --no-pager diff -- README.txt plan.txt
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git add -- README.txt
git status --short
git --no-pager diff --cached -- README.txt
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
notepad.exe .\README.txt
}

. {
git status --short
git --no-pager diff -- README.txt
git --no-pager diff --cached -- README.txt
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git add -- plan.txt
git diff --cached --name-only
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git restore --staged -- plan.txt
git diff --cached --name-only
Get-Content -LiteralPath 'plan.txt'
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git --no-pager diff --cached
git commit -m "Beskriv starttid for turen"
if ($LASTEXITCODE -ne 0) { throw "STOPP: Commit ble ikke laget." }
git --no-pager log --oneline -2
git status --short
}

. {
git --no-pager show HEAD:README.txt
Get-Content -LiteralPath 'README.txt'
}

. {
if ((Get-Location).Path -ne $practiceRoot) { throw 'STOPP: Gaa tilbake til ovingsmappen.' }
git add -- README.txt
notepad.exe .\plan.txt
}

. {
git status --short
git --no-pager diff --cached
git --no-pager diff
}
